css = ['/* Generated by tools/build-icons.py - stroke icons rendered as CSS masks. */',
       '.i{display:inline-block;width:1.15em;height:1.15em;flex:none;vertical-align:-.2em;background-color:currentColor;'
       '-webkit-mask:var(--i) center/contain no-repeat;mask:var(--i) center/contain no-repeat}',
       '.i.sm{width:1em;height:1em}.i.lg{width:1.5em;height:1.5em}.i.xl{width:2.4em;height:2.4em}']
for name, body in I.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#000" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">{body}</svg>'
    css.append(f'.i-{name}{{--i:url("data:image/svg+xml,{urllib.parse.quote(svg, safe=" =:/")}")}}')
out = pathlib.Path(__file__).resolve().parent.parent / 'public' / 'css' / 'icons.css'
out.write_text('\n'.join(css) + '\n')
print(f'{len(I)} icons -> {out}')
